<script setup lang="ts">
import{computed,onMounted,reactive,ref,watch}from'vue'
import{useRoute}from'vue-router'
import{api,run}from'../api'
import type{Row}from'../types'
import{state,refreshMine}from'../store';import{roomNames,roomUsages}from'../membership';import{date,label}from'../utils'
const route=useRoute(),roomMode=computed(()=>route.path==='/rooms'),records=ref<Row[]>([]),busy=ref(false),error=ref(''),formRef=ref()
const form=reactive({title:'',description:'',contact:state.user?.contact||'',room:'和光文体中心单车俱乐部',usage:'训练',otherUsage:'',startDay:'',startTime:'',endDay:'',endTime:''})
const allowedRooms=computed<string[]>(()=>state.mine.member?.allowedRooms||[]),allowedUsages=computed<string[]>(()=>state.mine.member?.allowedUsages||[]),canApplyRoom=computed(()=>allowedRooms.value.length>0);
watch([allowedRooms,allowedUsages],()=>{if(!allowedRooms.value.includes(form.room))form.room=allowedRooms.value[0]||'北三骑行室';if(!allowedUsages.value.includes(form.usage))form.usage=allowedUsages.value[0]||'存放车辆'},{immediate:true});
const mine=computed(()=>records.value.filter(r=>r.kind===(roomMode.value?'ROOM':'SUGGESTION')))
const rules={contact:[{required:true,message:'请填写联系方式',trigger:'blur'}],title:[{required:true,message:'请填写活动名称',trigger:'blur'}],description:[{required:true,message:'请填写申请说明',trigger:'blur'}],otherUsage:[{required:true,message:'请填写具体使用方式',trigger:'blur'}]}
async function load(){error.value='';try{records.value=await api('/riding-requests')}catch(e){error.value=e instanceof Error?e.message:'记录加载失败'}}
function instant(day:string,time:string){return day&&time?new Date(day+'T'+time+':00+08:00').toISOString():null}
async function submit(){
 if(roomMode.value&&!canApplyRoom.value){error.value='成员身份尚未审核或分类，暂不能申请使用场地';return}
 if(!await formRef.value?.validate().catch(()=>false))return
 let startsAt=null,endsAt=null
 if(roomMode.value){startsAt=instant(form.startDay,form.startTime);endsAt=instant(form.endDay,form.endTime);if(!startsAt||!endsAt||Date.parse(startsAt)<=Date.now()||Date.parse(endsAt)<=Date.parse(startsAt)){error.value='请选择未来的开始时间，结束时间须晚于开始时间';return}}
 busy.value=true;error.value='';try{await api('/riding-requests','POST',{kind:roomMode.value?'ROOM':'SUGGESTION',title:roomMode.value?form.room+' · '+form.usage:form.title,description:form.description,contact:form.contact,room:roomMode.value?form.room:'',usage:roomMode.value?form.usage:'',otherUsage:form.usage==='其他'?form.otherUsage:'',startsAt,endsAt});form.title='';form.description='';form.otherUsage='';await load();await run(async()=>{},'申请已提交，可在下方查看处理结果')}catch(e){error.value=e instanceof Error?e.message:'提交失败'}finally{busy.value=false}
}
watch(()=>route.path,()=>{error.value='';formRef.value?.clearValidate()});onMounted(async()=>{await refreshMine();await load()})
</script>
<template><div class="page-content"><div class="page-heading"><div><div class="eyebrow">征途单车俱乐部 · 骑行服务</div><h1>{{roomMode?'骑行室使用':'活动建议'}}<span class="greeting-dot">.</span></h1><p>{{roomMode?'选择骑行室、使用方式及起止时间，向管理员提交申请。':'想和骑友一起出发？提出你的集体骑行活动建议。'}}</p></div></div><div class="request-layout"><section class="panel request-form"><h3>{{roomMode?'创建使用申请':'申请集体骑行活动'}}</h3><p class="muted small">联系方式仅供本人及管理员查看。提交申请后请等待审核。</p><div v-if="roomMode" class="info-box">{{!canApplyRoom?'成员身份尚未审核或分类，暂不能申请场地；请联系管理员确认。':state.mine.member?.memberType==='SOCIETY'?'社团成员仅可在北三骑行室存取个人自行车；不得在室内开展其他活动或擅用物品设施，特殊情况请提前联系管理员。':'俱乐部成员可申请两个场地用于存车、训练、维修或休息，请提前申请并遵守管理安排。'}}</div><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="submit">
<template v-if="roomMode"><el-form-item label="选择骑行室" required><el-radio-group v-model="form.room"><el-radio-button v-for="place in roomNames" :key="place" :value="place" :disabled="!allowedRooms.includes(place)">{{place}}</el-radio-button></el-radio-group></el-form-item><el-form-item label="使用方式" required><el-radio-group v-model="form.usage"><el-radio-button v-for="value in roomUsages" :key="value" :value="value" :disabled="!allowedUsages.includes(value)">{{value}}</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="form.usage==='其他'" label="具体使用方式" prop="otherUsage"><el-input v-model="form.otherUsage" maxlength="200" placeholder="请说明你将如何使用骑行室"/></el-form-item><div class="request-time-grid"><el-form-item label="开始时间（北京时间）" required><input v-model="form.startDay" type="date" aria-label="开始日期" class="native-select"><el-time-picker v-model="form.startTime" format="HH:mm" value-format="HH:mm" placeholder="滚动选择时、分" aria-label="开始时分"/></el-form-item><el-form-item label="结束时间（北京时间）" required><input v-model="form.endDay" type="date" aria-label="结束日期" class="native-select"><el-time-picker v-model="form.endTime" format="HH:mm" value-format="HH:mm" placeholder="滚动选择时、分" aria-label="结束时分"/></el-form-item></div><p class="muted small">点击时间后滚动选择小时和分钟；申请通过后方可按安排使用。</p></template>
<el-form-item v-else label="建议活动名称" prop="title"><el-input v-model="form.title" maxlength="120" placeholder="例如：周末校园周边集体骑行"/></el-form-item><el-form-item label="联系方式（手机 / 微信 / QQ）" prop="contact"><el-input v-model="form.contact" maxlength="120" placeholder="请填写便于管理员联系的方式"/></el-form-item><el-form-item :label="roomMode?'使用说明':'活动建议与期望安排'" prop="description"><el-input v-model="form.description" type="textarea" :rows="4" maxlength="2000" show-word-limit :placeholder="roomMode?'说明使用人数、需求等情况':'说明期望路线、时间、人数及活动目的，便于管理员评估'"/></el-form-item><div v-if="error" class="info-box" role="alert">{{error}}</div><el-button type="primary" native-type="submit" :loading="busy" :disabled="roomMode&&!canApplyRoom">提交{{roomMode?'使用申请':'活动建议'}}</el-button></el-form></section>
<section class="panel request-records"><div class="section-heading"><h3>我的{{roomMode?'使用申请':'活动建议'}}</h3><el-button link @click="load">刷新记录</el-button></div><el-empty v-if="!mine.length" description="暂无申请记录"/><article v-for="r in mine" :key="r.id" class="request-record"><b>{{r.title}}</b><el-tag :type="r.status==='APPROVED'?'success':r.status==='REJECTED'?'danger':'warning'">{{label(r.status)}}</el-tag><p>{{r.description}}</p><p v-if="r.kind==='ROOM'">{{r.room}} · {{r.usage==='其他'?r.otherUsage:r.usage}}<br>{{date(r.startsAt,true)}} — {{date(r.endsAt,true)}}</p><p>联系方式：{{r.contact}}</p><small class="muted">提交于 {{date(r.createdAt,true)}}</small><div v-if="r.reviewNote" class="info-box">管理员意见：{{r.reviewNote}}</div></article></section></div></div></template>
<style scoped>
.request-layout{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}.request-form,.request-records{padding:28px}.request-form h3{margin-bottom:12px}.request-form>p{margin-bottom:24px;line-height:1.8}.request-time-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.request-time-grid .el-form-item :deep(.el-form-item__content){display:grid;gap:10px;width:100%}.request-time-grid :deep(.el-date-editor.el-input){width:100%}.request-record{padding:22px 0;border-top:1px solid var(--border)}.request-record>b{display:block;margin-bottom:10px}.request-record p{font-size:12px;line-height:1.9;margin:12px 0;white-space:pre-wrap;overflow-wrap:anywhere}.request-form :deep(.el-radio-group){gap:0;flex-wrap:wrap}.request-form :deep(.el-radio-button__inner){padding:12px}.request-record :deep(.info-box){white-space:pre-wrap}@media(max-width:1000px){.request-layout{grid-template-columns:1fr}}@media(max-width:600px){.request-form,.request-records{padding:20px}.request-time-grid{grid-template-columns:1fr}.request-form :deep(.el-radio-button__inner){padding:11px 9px;font-size:12px}}
</style>
